src('ncaa_lsdbi_2023_32', 'NCAA Legislative Services Database (LSDBi), Division I Proposal 2023-32, Football -- Initial Counter and Annual Signing Limits (Adopted Final, effective immediately, https://web3.ncaa.org/lsdbi/search/proposalView?id=107322)', 'ncaa-official', True)
add('F-recruiting-0031', 'ncaa_lsdbi_2023_32', 'Intent and Bylaw 13.9.3.3 (text being amended)', 'In bowl subdivision football, there shall be an annual limit of 25 on the number of prospective student-athletes who may sign a National Letter of Intent or an institutional offer of financial aid and student-athletes who may sign a financial aid agreement for the first time. [Intent of the adopted proposal: to eliminate that annual limit of 25.]', 25)
